from qbank_authoring import ref,finalize
EV=ref('AAPM&R Peripheral Polyneuropathy Evaluation','https://now.aapmr.org/approach-to-peripheral-polyneuropathy-evaluation-and-differential-diagnosis/')
PN=ref('MSD Manual Professional: Peripheral Neuropathy','https://www.msdmanuals.com/professional/neurologic-disorders/peripheral-nervous-system-and-motor-unit-disorders/peripheral-neuropathy?ruleredirectid=741')
PAIN=ref('AAN Painful Diabetic Polyneuropathy Guideline Update','https://pubmed.ncbi.nlm.nih.gov/34965987/')
CMT=ref('GeneReviews: Charcot–Marie–Tooth Hereditary Neuropathy Overview','https://www.ncbi.nlm.nih.gov/books/NBK1358/')
HN=ref('GeneReviews: Hereditary Neuropathy with Liability to Pressure Palsies','https://www.ncbi.nlm.nih.gov/books/NBK1392/')
AM=ref('GeneReviews: Hereditary Transthyretin Amyloidosis','https://www.ncbi.nlm.nih.gov/books/NBK1194/')
